```python
# Define the restaurant menu
menu = {
    "pizza": 15,
    "salad": 10,
    "burger": 12,
    "drink": 3,
}

def calculate_total_cost(order):
    """Calculate the total cost of an order."""
    total_cost = 0
    for item, quantity in order.items():
        cost = menu[item] * quantity
        total_cost += cost
    return total_cost

def main():
    while True:
        user_input = input("Enter an item to order (or 'quit' to finish): ").lower()

        if user_input == "quit":
            print("Thank you for ordering!")
            break

        if user_input not in menu:
            print(f"Sorry, '{user_input}' is not on the menu. Please try again.")
            continue

        quantity = int(input(f"Enter the quantity of '{user_input}': "))

        order = {user_input: quantity}
        total_cost = calculate_total_cost(order)

        print(f"Total cost: {total_cost}")

if __name__ == "__main__":
    main()
```

This program will keep asking the user to enter an item to order until they type "quit". For each item ordered, it will prompt the user to enter the quantity, calculate the cost, and display the total cost.
